class Solution {
    static const long long MOD = 1000000007LL;
    struct Mat {
        long long a[2][2];
        Mat(bool identity = false) {
            for (int i = 0; i < 2; ++i)
                for (int j = 0; j < 2; ++j)
                    a[i][j] = (identity && i == j) ? 1 : 0;
        }
    };
    Mat mul(const Mat& x, const Mat& y) {
        Mat z;
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                for (int t = 0; t < 2; ++t)
                    z.a[i][j] = (z.a[i][j] + x.a[i][t] * y.a[t][j]) % MOD;
        return z;
    }
public:
    int distinctPaths(int n, vector<int>& parent,
                      vector<vector<int>>& gates,
                      vector<vector<int>>& queries) {
        const int LOG = 16;
        vector<vector<int>> up(LOG, vector<int>(n));
        vector<vector<Mat>> trans(LOG, vector<Mat>(n, Mat(true)));
        vector<vector<int>> children(n);
        for (int v = 1; v < n; ++v) children[parent[v]].push_back(v);
        vector<int> depth(n, 0), order(1, 0);
        for (int p = 0; p < (int)order.size(); ++p) {
            int u = order[p];
            for (int v : children[u]) {
                depth[v] = depth[u] + 1;
                order.push_back(v);
            }
        }
        for (int v = 0; v < n; ++v) {
            up[0][v] = v == 0 ? 0 : parent[v];
            if (v != 0) {
                trans[0][v].a[0][0] = gates[v][1];
                trans[0][v].a[0][1] = gates[v][2];
                trans[0][v].a[1][0] = gates[v][2];
                trans[0][v].a[1][1] = gates[v][0];
            }
        }
        for (int j = 1; j < LOG; ++j)
            for (int v = 0; v < n; ++v) {
                int mid = up[j - 1][v];
                up[j][v] = up[j - 1][mid];
                trans[j][v] = mul(trans[j - 1][v], trans[j - 1][mid]);
            }
        auto ascend = [&](int v, int steps) {
            for (int j = 0; j < LOG; ++j)
                if (steps & (1 << j)) v = up[j][v];
            return v;
        };
        auto ways = [&](int v, int anc, int card) {
            Mat result(true);
            int steps = depth[v] - depth[anc];
            for (int j = 0; j < LOG; ++j)
                if (steps & (1 << j)) {
                    result = mul(result, trans[j][v]);
                    v = up[j][v];
                }
            return (result.a[card][0] + result.a[card][1]) % MOD;
        };
        int answer = 0;
        for (const auto& q : queries) {
            int a = q[0], b = q[2];
            int x = a, y = b;
            if (depth[x] < depth[y]) swap(x, y);
            x = ascend(x, depth[x] - depth[y]);
            if (x != y) {
                for (int j = LOG - 1; j >= 0; --j)
                    if (up[j][x] != up[j][y]) {
                        x = up[j][x];
                        y = up[j][y];
                    }
                x = up[0][x];
            }
            int lca = x;
            long long total = ways(a, lca, q[1]) * ways(b, lca, q[3]) % MOD;
            answer ^= (int)total;
        }
        return answer;
    }
};
